
-- 
export type IEnumerable<T> = { T }

-- 
export type CancellationToken = {
	IsCancelled: boolean,
}


export type IConfigurationBuilder = {
    Add:(self:IConfigurationBuilder, source: IConfigurationSource, deserializer: ((data: any) -> {})?)->(),
    Build:(self:IConfigurationBuilder)->()
}

export type IConfigurationSource = {
	Name: string,
	Type: "Module" | "Factory",

	-- 配置源实例
	Instance: Instance,

	-- 如果Type是Factory，则Factory不能为空
	Factory: ((ins: Instance) -> any)?,
}

return {}
